// Exact expected-side 541 -> 558 composition; current entries are never projected backwards.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {interruptionEntry,interruptionExpectedRegistry,interruptionSourceText} from '../interruption-observation/verify-reference.mjs';
import {algorithmEntry} from '../algorithm-residuals/verify-component.mjs';
export const jointSha=x=>createHash('sha256').update(x).digest('hex');
export const jointCanon=x=>JSON.stringify((function sort(v){if(Array.isArray(v))return v.map(sort);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])]));return v;})(x));
const proofBytes=fs.readFileSync(new URL('./joint-proof.json',import.meta.url));assert.equal(jointSha(proofBytes),'0df8a71700b464299001989104676992fdda9a454b038de19c7b171c0c2c96a0','exact joint proof');
export const jointProof=JSON.parse(proofBytes);
const p=jointProof,get=(o,a)=>a.reduce((v,k)=>v[k],o),set=(o,a,v)=>a.slice(0,-1).reduce((v,k)=>v[k],o)[a.at(-1)]=v,key=r=>JSON.stringify([r.entryId,r.path]);
assert.equal(p.records.length,20);assert.equal(new Set(p.records.map(key)).size,20);assert.equal(Object.keys(p.beforeEntries).length,17);assert.equal(p.entryOrder.length,803);assert.equal(new Set(p.entryOrder).size,803);
for(const [relative,h]of Object.entries(p.componentPins))assert.equal(jointSha(fs.readFileSync(new URL('../'+relative,import.meta.url))),h,'independent component input '+relative);
for(const r of p.records){assert.equal(jointSha(r.before),r.beforeSha256);assert.equal(jointSha(r.after),r.afterSha256);assert.equal(get(p.beforeEntries[r.entryId],r.path),r.before);assert.equal(get(p.afterEntries[r.entryId],r.path),r.after);}
for(const [id,e]of Object.entries(p.beforeEntries)){const after=algorithmEntry(interruptionEntry(e));assert.deepEqual(after,p.afterEntries[id]);assert.equal(jointSha(jointCanon(e)),p.beforeCanonicalHashes[id]);assert.equal(jointSha(jointCanon(after)),p.afterCanonicalHashes[id]);}
export function jointEntry(expected541){const id=expected541.id;if(!Object.hasOwn(p.beforeEntries,id))return structuredClone(expected541);assert.deepEqual(expected541,p.beforeEntries[id],'exact full541 expected entry '+id);const result=algorithmEntry(interruptionEntry(expected541));assert.deepEqual(result,p.afterEntries[id]);return result;}
export function jointEntryHash(id,expected541){if(!Object.hasOwn(p.beforeEntries,id))return expected541;assert.equal(expected541,p.beforeCanonicalHashes[id],'exact541 entire-entry expected hash '+id);return p.afterCanonicalHashes[id];}
export function jointLeaf(id,a,old){const r=p.records.find(r=>r.entryId===id&&JSON.stringify(r.path)===JSON.stringify(a));if(!r)return old;assert.equal(old,r.before,'exact541 expected leaf '+id);return r.after;}
export function jointHash(id,a,old){const r=p.records.find(r=>r.entryId===id&&JSON.stringify(r.path)===JSON.stringify(a));if(!r)return old;assert.equal(old,r.beforeSha256,'exact541 expected leaf hash '+id);return r.afterSha256;}
export function assertJointEntries(input){const entries=input instanceof Map?[...input.values()]:input;assert.equal(entries.length,803);assert.deepEqual(entries.map(e=>e.id),p.entryOrder,'complete803 canonical traversal unchanged');assert.equal(new Set(entries.map(e=>e.id)).size,803);for(const e of entries){assert.equal(jointSha(jointCanon(e)),p.afterCanonicalHashes[e.id],'full558 entry '+e.id);if(Object.hasOwn(p.afterEntries,e.id))assert.deepEqual(e,p.afterEntries[e.id]);}return {leaves:20,changedEntries:17,corpusEntries:803};}
export function jointExpectedRegistry(expected541){assert.equal(expected541.records.length,541);assert.equal(jointSha(jointCanon(expected541)),p.registryBeforeCanonicalSha256,'complete exact541 expected registry');const result=interruptionExpectedRegistry(expected541);for(const row of p.algorithmRegistryCompositions){assert.deepEqual(result.records[row.index],row.before);result.records[row.index]=structuredClone(row.after);}const keys=new Set(result.records.map(key));for(const row of p.algorithmNewRegistryRecords){assert.ok(!keys.has(key(row)));keys.add(key(row));result.records.push(structuredClone(row));}assert.equal(result.records.length,558);assert.equal(jointSha(jointCanon(result)),p.registryAfterCanonicalSha256);return result;}
export function assertJointRegistry(actual){assert.equal(actual.records.length,558);assert.equal(new Set(actual.records.map(key)).size,558);assert.equal(jointSha(jointCanon(actual)),p.registryAfterCanonicalSha256,'complete current558 registry object required');return {before:541,after:558,composed:3,appended:17};}
let sources;
export function jointSourceProof(){if(!sources){const raw=fs.readFileSync(new URL('./source-transitions.json',import.meta.url));assert.equal(jointSha(raw),p.sourceProofSha256);sources=JSON.parse(raw);}return sources;}
export function jointSourceText(target,old){const s=jointSourceProof(),r=s.replacements.find(r=>r.target===target);if(!r){const a=s.assets.find(r=>r.target===target);if(!a)return old;assert.equal(jointSha(old),a.beforeSha256,'exact frozen541 asset text '+target);const next=interruptionSourceText(target,old);assert.equal(jointSha(next),a.afterSha256,'exact independent interruption asset mapping '+target);return next;}assert.equal(old,r.before,'exact541 source text '+target);return r.after;}
export function jointSourceHash(target,old){const r=[...jointSourceProof().replacements,...jointSourceProof().assets].find(r=>r.target===target);if(!r)return old;assert.equal(old,r.beforeSha256,'exact541 source hash '+target);return r.afterSha256;}
export function verifyJointSourceRow(r){assert.equal(jointSha(r.before),r.beforeSha256);assert.equal(jointSha(r.after),r.afterSha256);const b=Buffer.from(r.before),parts=[];let pos=0;for(const e of r.edits){assert.ok(Number.isInteger(e.beforeStartByte)&&e.beforeStartByte>=pos);assert.ok(Number.isInteger(e.beforeEndByte)&&e.beforeEndByte>=e.beforeStartByte&&e.beforeEndByte<=b.length);assert.equal(b.subarray(e.beforeStartByte,e.beforeEndByte).toString(),e.before);parts.push(b.subarray(pos,e.beforeStartByte),Buffer.from(e.after));pos=e.beforeEndByte;}parts.push(b.subarray(pos));assert.equal(Buffer.concat(parts).toString(),r.after,'exact reviewed source reconstructed');}
export function assertJointSources(siteRoot=new URL('../../../',import.meta.url)){const root=siteRoot instanceof URL?fileURLToPath(siteRoot):siteRoot,s=jointSourceProof(),seen=new Set();assert.equal(s.clones.length,7);assert.equal(s.replacements.length,9);assert.equal(s.assets.length,19);for(const r of [...s.clones,...s.replacements]){assert.ok(!seen.has(r.target));seen.add(r.target);verifyJointSourceRow(r);if(r.originalTarget!==r.target){assert.ok(r.originalTarget.startsWith('tests/fixtures/tenth-low-coupling/'));assert.equal(fs.readFileSync(path.join(root,r.originalTarget),'utf8'),r.before,'immutable original541 executable');}assert.equal(fs.readFileSync(path.join(root,r.target),'utf8'),r.after,'exact installed558 source '+r.target);}for(const r of s.assets){assert.equal(jointSha(fs.readFileSync(path.join(root,r.target))),r.afterSha256);assert.equal(jointSha(fs.readFileSync(path.join(root,r.target.replace(/^public\//,'dist/')))),r.afterSha256);}for(const [relative,h]of Object.entries(p.originalFixturePins))assert.equal(jointSha(fs.readFileSync(path.join(root,relative))),h,'original fixture/oracle '+relative);return {clones:7,replacements:9,assets:19,originalFixtures:Object.keys(p.originalFixturePins).length,originalFixtureWrites:0};}
